  <div class="task-table" id="taskTable">
    <!-- Table header -->
    <div class="header">ID</div>
    <div class="header">Title</div>
    <div class="header">Due Date</div>
    <div class="header">Status</div>
    <div class="header">Actions</div>
  </div>

  <script>
    const tasks = [
      { "id": 1, "title": "Design Homepage", "dueDate": "2023-10-15", "status": "pending" },
      { "id": 2, "title": "Develop Login Module", "dueDate": "2023-10-20", "status": "pending" },
      { "id": 3, "title": "Test Payment Gateway", "dueDate": "2023-10-25", "status": "completed" }
    ];

    const taskTable = document.getElementById('taskTable');

    tasks.forEach(task => {
      const row = document.createElement('div');
      row.className = `task-row ${task.status === 'completed' ? 'completed' : ''}`;

      row.innerHTML = `
        <div><time>${task.id}</time></div>
        <div>${task.title}</div>
        <div>${task.dueDate}</div>
        <div>${task.status}</div>
        <div><button onclick="markCompleted(${task.id})">Complete</button></div>
      `;

      taskTable.appendChild(row);
    });

    function markCompleted(taskId) {
      const task = tasks.find(t => t.id === taskId);
      if (task) {
        task.status = "completed";
        updateTaskTable();
      }
    }

    function updateTaskTable() {
      // Clear the task table, keeping the header
      const headerElements = taskTable.querySelectorAll('.header');
      taskTable.innerHTML = '';
      headerElements.forEach(header => taskTable.appendChild(header));

      tasks.forEach(task => {
        const row = document.createElement('div');
        row.className = `task-row ${task.status === 'completed' ? 'completed' : ''}`;

        row.innerHTML = `
          <div><time>${task.id}</time></div>
          <div>${task.title}</div>
          <div>${task.dueDate}</div>
          <div>${task.status}</div>
          <div><button onclick="markCompleted(${task.id})">Complete</button></div>
        `;

        taskTable.appendChild(row);
      });
    }
  </script>
</body>
</html>
```

